17: @Component
18: @Order(Ordered.HIGHEST_PRECEDENCE)
19: public class CorrelationFilter extends OncePerRequestFilter {
20: 
21:     static final String CORRELATION = "X-Correlation-ID";
22: 
23:     @Override
24:     protected void doFilterInternal(
25:             HttpServletRequest request,
26:             HttpServletResponse response,
27:             FilterChain filterChain) throws ServletException, IOException {
28:         String correlationId = request.getHeader(CORRELATION);
29:         if (correlationId == null || correlationId.isBlank()) {
30:             correlationId = UUID.randomUUID().toString();
31:         }
32:         MDC.put("correlationId", correlationId);
33:         rememberTraceParent(request);
34:         response.setHeader(CORRELATION, correlationId);
35:         try {
36:             filterChain.doFilter(request, response);
37:         } finally {
38:             MDC.clear();
39:         }
40:     }
41: 
42:     private static void rememberTraceParent(HttpServletRequest request) {
43:         String traceParent = request.getHeader("traceparent");
44:         if (traceParent != null && !traceParent.isBlank()) {
45:             MDC.put("traceparent", traceParent);
46:         }
47:     }
48: }

