"package com.example.app.config;

public final class Encode {

    private Encode() {
    }

    public static String forJava(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder(value.length() + 16);
        for (int i = 0; i < value.length(); i++) {
            appendEscapedChar(sb, value.charAt(i));
        }
        return sb.toString();
    }

    private static void appendEscapedChar(StringBuilder sb, char ch) {
        switch (ch) {
            case '\r' -> sb.append("\\r");
            case '\n' -> sb.append("\\n");
            case '\t' -> sb.append("\\t");
            case '\b' -> sb.append("\\b");
            case '\f' -> sb.append("\\f");
            case '\\' -> sb.append("\\\\");
            case '"' -> sb.append("\\\"");
            case '\'' -> sb.append("\\'");
            default -> {
                if (ch < 0x20 || ch == 0x7f) {
                    sb.append(String.format("\\u%04x", (int) ch));
                } else {
                    sb.append(ch);
                }
            }
        }
    }
}
"

"package com.example.app.iam.port;

import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public record SessionClaims(
        String sessionId,
        UUID userId,
        String workspaceEmail,
        List<String> roles,
        String effectiveViewAsRole,
        boolean readOnlyOverlay,
        Instant expiresAt) {

    public SessionClaims {
        Objects.requireNonNull(sessionId, "sessionId must not be null");
        Objects.requireNonNull(userId, "userId must not be null");
        Objects.requireNonNull(workspaceEmail, "workspaceEmail must not be null");
        roles = roles == null ? List.of() : List.copyOf(roles);
        Objects.requireNonNull(expiresAt, "expiresAt must not be null");
    }
}
