            String sessionId,
            String effectiveViewAsRole,
            boolean readOnlyOverlay);

    void revokeSession(String sessionId);

    void revokeToken(String tokenJti, Duration remainingTtl);

    boolean isTokenRevoked(String tokenJti);
}
