"package com.example.app.execution.adapter;

import java.time.Duration;
import java.util.Objects;

import com.example.app.execution.port.DistributedLockPort;
import com.example.app.iam.port.RedisKeyValueBackend;
import org.springframework.stereotype.Component;

@Component
public class RedisDistributedLockAdapter implements DistributedLockPort {

    private static final String LOCK_KEY_PREFIX = "portal:lock:";

    private final RedisKeyValueBackend backend;

    public RedisDistributedLockAdapter(RedisKeyValueBackend backend) {
        this.backend = Objects.requireNonNull(backend, "backend must not be null");
    }

    @Override
    public boolean acquireLease(String lockKey, String ownerToken, Duration leaseDuration) {
        Objects.requireNonNull(lockKey, "lockKey must not be null");
        Objects.requireNonNull(ownerToken, "ownerToken must not be null");
        return backend.setIfAbsent(LOCK_KEY_PREFIX + lockKey, ownerToken, leaseDuration);
    }

    @Override
    public boolean renewLease(String lockKey, String ownerToken, Duration leaseDuration) {
        Objects.requireNonNull(lockKey, "lockKey must not be null");
        Objects.requireNonNull(ownerToken, "ownerToken must not be null");
        return backend.renewIfValueMatches(LOCK_KEY_PREFIX + lockKey, ownerToken, leaseDuration);
    }

    @Override
    public boolean releaseLease(String lockKey, String ownerToken) {
        Objects.requireNonNull(lockKey, "lockKey must not be null");
        Objects.requireNonNull(ownerToken, "ownerToken must not be null");
        return backend.deleteIfValueMatches(LOCK_KEY_PREFIX + lockKey, ownerToken);
    }
}
